```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    double suma = 0;
    for (int v : dane) suma += v;
    double avg = suma / dane.size();
    int maxLen = 0, maxStart = 0;
    int curLen = 0, curStart = 0;
    for (int i = 0; i < (int)dane.size(); i++) {
        if (dane[i] > avg) {
            if (curLen == 0) curStart = i;
            curLen++;
        } else {
            if (curLen > maxLen) {
                maxLen = curLen;
                maxStart = curStart;
            }
            curLen = 0;
        }
    }
    if (curLen > maxLen) {
        maxLen = curLen;
        maxStart = curStart;
    }
    cout << fixed << setprecision(2);
    cout << "Srednia: " << avg << endl;
    cout << "Najdluzszy ciag powyzej sredniej: " << maxLen << " elementow" << endl;
    cout << "Poczatek: pozycja " << maxStart + 1 << endl;
    return 0;
}
```

Weryfikacja:
- Suma: 3+8+12+7+5+10+4+6+1+9 = 65, srednia = 6.50
- Elementy > 6.50: 8(pos2), 12(pos3), 7(pos4), 10(pos6), 9(pos10)
- Ciagi powyzej: (8,12,7) dl=3, (10) dl=1, (9) dl=1
- Najdluzszy: 3, poczatek pozycja 2
